// eslint-disable-next-line @github-ui/github-monorepo/filename-convention
import {TextureLoader} from 'three'

interface Image {
  src: string
  texture: null
  flipY: boolean
  encoding?: number
}

interface Images {
  starShape: Image
  starShapeShadow: Image
  starShapeGlow: Image
}

const imagePath = '/images/modules/site/lab/'

export default class Assets {
  images: Images = {
    starShape: {
      src: `${imagePath}star-shape.jpg`,
      texture: null,
      flipY: false,
    },
    starShapeShadow: {
      src: `${imagePath}star-shape-shadow.jpg`,
      texture: null,
      flipY: false,
    },
    starShapeGlow: {
      src: `${imagePath}star-shape-glow.jpg`,
      texture: null,
      flipY: false,
    },
  }
  isLoaded: boolean = false

  async load(callback: {(): void; (): void}) {
    const allPromisess = [...this.loadImages()]

    try {
      await Promise.all(allPromisess)

      this.isLoaded = true

      // All assets loaded
      if (callback) callback()
    } catch (error) {
      // eslint-disable-next-line no-console
      console.log('Error loading assets', error)
    }
  }

  loadImages() {
    const loader = new TextureLoader()

    const promises = Object.values(this.images).map(
      image =>
        new Promise((resolve, reject) => {
          loader.load(
            image.src,
            texture => {
              image.texture = texture
              texture.flipY = image.flipY
              if (image.encoding) texture.encoding = image.encoding
              resolve(texture)
            },
            undefined,
            error => reject(error),
          )
        }),
    )

    return promises
  }
}
